{
  "findings": [
    {
      "check_id": "CKV_AWS_79",
      "title": "Ensure Instance Metadata Service Version 1 is not enabled",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "MEDIUM",
      "explanation": "Instance Metadata Service Version 1 (IMDSv1) is less secure than IMDSv2 because it is vulnerable to SSRF attacks. IMDSv2 should be enforced to enhance security."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "Ensure all data stored in the Launch configuration or instance Elastic Blocks Store is securely encrypted",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "MEDIUM",
      "explanation": "The launch configuration does not specify encryption for the root block device or additional EBS volumes. Unencrypted storage can expose sensitive data if the volume is compromised."
    }
  ],
  "patched_code": "resource \"aws_launch_configuration\" \"levelup-launchconfig\" {\n  name_prefix     = \"levelup-launchconfig\"\n  image_id        = lookup(var.AMIS, var.AWS_REGION)\n  instance_type   = \"t2.micro\"\n  key_name        = aws_key_pair.levelup_key.key_name\n\n  metadata_options {\n    http_tokens = \"required\"\n  }\n\n  root_block_device {\n    encrypted = true\n  }\n}",
  "fix_summary": "Enforced IMDSv2 by setting 'http_tokens' to 'required' in the 'metadata_options' block. Enabled encryption for the root block device by adding the 'encrypted = true' property in the 'root_block_device' block."
}
